import * as React from 'react';
import { LineChartPro } from '@mui/x-charts-pro/LineChartPro';

import Typography from '@mui/material/Typography';
import Stack from '@mui/material/Stack';
import ToggleButtonGroup from '@mui/material/ToggleButtonGroup';
import ToggleButton from '@mui/material/ToggleButton';
import { ScatterChartPro } from '@mui/x-charts-pro/ScatterChartPro';
import { BarChartPro } from '@mui/x-charts-pro/BarChartPro';
import { BarChartPremium } from '@mui/x-charts-premium/BarChartPremium';
import { CandlestickChart } from '@mui/x-charts-premium/CandlestickChart';

import {
  dateAxisFormatter,
  usUnemploymentRate,
} from '../dataset/usUnemploymentRate';
import { globalCo2GdpPopulation } from '../dataset/globalCo2GdpPopulation';
import { globalBirthPerWoman } from '../dataset/globalBirthsPerWoman';
import {
  continents,
  countriesInContinent,
  countryData,
} from '../dataset/countryData';
import { shareOfRenewables } from '../dataset/shareOfRenewables';
import { populationPrediction2050 } from '../dataset/populationPrediction2050';
import { temperatureBerlinPorto } from '../dataset/temperatureBerlinPorto';
import sp500 from '../dataset/sp500-intraday.json';

const lineData = usUnemploymentRate.map((d) => d.rate / 100);

const percentageFormatter = new Intl.NumberFormat(undefined, {
  style: 'percent',
  minimumSignificantDigits: 1,
  maximumSignificantDigits: 3,
});
const gdpPerCapitaFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
});
const populationFormatter = new Intl.NumberFormat('en-US', { notation: 'compact' });
const dayFormatter = new Intl.DateTimeFormat(undefined, {
  day: 'numeric',
  month: '2-digit',
  year: 'numeric',
});

const commonXAxisProps = {
  id: 'x',
  zoom: { filterMode: 'discard', slider: { enabled: true, preview: true } },
};

const commonProps = {
  initialZoom: [{ axisId: 'x', start: 20, end: 80 }],
  height: 400,
};

const lineXAxis = {
  scaleType: 'time',
  id: 'x',
  data: usUnemploymentRate.map((d) => d.date),
  valueFormatter: dateAxisFormatter,
};

const lineSettings = {
  yAxis: [
    {
      id: 'y',
      width: 44,
      valueFormatter: (v) => percentageFormatter.format(v),
      min: 0,
    },
  ],
  series: [
    {
      data: lineData,
      valueFormatter: (v) => percentageFormatter.format(v),
    },
  ],
};

const areaXAxis = {
  id: 'x',
  data: new Array(101).fill(null).map((_, i) => i),
  label: 'Age',
  valueFormatter: (v) => (v === 100 ? '100+' : Math.round(v).toString()),
};

const areaSettings = {
  yAxis: [
    {
      id: 'y',
      width: 44,
      valueFormatter: (v) => populationFormatter.format(v),
    },
  ],
  series: ['Europe', 'Asia', 'Americas', 'Africa', 'Oceania'].map((continent) => ({
    data: populationPrediction2050
      .filter((point) => point.location === continent)
      .map((point) => point.value),
    area: true,
    label: continent,
    stack: 'population',
    valueFormatter: (v) => populationFormatter.format(v),
  })),
};

const scatterXAxis = {
  valueFormatter: (v) => gdpPerCapitaFormatter.format(v),
};
const scatterSettings = {
  yAxis: [{ id: 'y', width: 16, min: 0 }],
  series: continents.map((continent) => ({
    label: continent,
    data: countriesInContinent[continent]
      .map((code) => ({
        id: code,
        x: globalCo2GdpPopulation.find((d) => d.code === code)?.gdpPerCapita,
        y: globalBirthPerWoman.find((d) => d.code === code)?.rate,
      }))
      .filter((d) => d.x !== undefined && d.y !== undefined),
    valueFormatter: (value) =>
      `${countryData[value.id].country} - Birth rate: ${value.y} - GDP per capita: ${gdpPerCapitaFormatter.format(value.x)}`,
  })),
};

const sortedShareOfRenewables = shareOfRenewables.toSorted(
  (a, b) => a.renewablesPercentage - b.renewablesPercentage,
);
const barXAxis = {
  data: sortedShareOfRenewables.map((d) => countryData[d.code].country),
  tickLabelStyle: { angle: -45 },
  height: 90,
};
const barSettings = {
  series: [
    {
      data: sortedShareOfRenewables.map((d) => d.renewablesPercentage / 100),
      valueFormatter: (v) => percentageFormatter.format(v),
    },
  ],
};

const rangeBarXAxis = {
  data: temperatureBerlinPorto.months,
  valueFormatter: (v, context) => (context.location === 'tick' ? v.slice(0, 3) : v),
};
const rangeBarSettings = {
  yAxis: [{ valueFormatter: (value) => `${value}°C` }],
  series: [
    {
      id: 'porto',
      type: 'rangeBar',
      label: 'Porto, Portugal',
      valueFormatter: (value) =>
        value === null ? null : `${value[0]}°C - ${value[1]}°C`,
      data: temperatureBerlinPorto.porto,
    },
    {
      id: 'berlin',
      type: 'rangeBar',
      label: 'Berlin, Germany',
      valueFormatter: (value) =>
        value === null ? null : `${value[0]}°C - ${value[1]}°C`,
      data: temperatureBerlinPorto.berlin,
    },
  ],
};

const candlestickXData = sp500.map((entry) => new Date(Date.parse(entry.date)));
const candlestickData = sp500.map((entry) => [
  entry.open,
  entry.high,
  entry.low,
  entry.close,
]);

export default function ZoomSliderPreview() {
  const [chartType, setChartType] = React.useState('bar');

  const handleChartType = (event, newChartType) => {
    if (newChartType !== null) {
      setChartType(newChartType);
    }
  };

  return (
    <Stack sx={{ width: '100%', gap: 2 }}>
      <ToggleButtonGroup
        value={chartType}
        exclusive
        onChange={handleChartType}
        aria-label="chart type"
        fullWidth
      >
        {['bar', 'rangeBar', 'line', 'area', 'scatter', 'candlestick'].map(
          (type) => (
            <ToggleButton key={type} value={type}>
              {type}
            </ToggleButton>
          ),
        )}
      </ToggleButtonGroup>
      {chartType === 'bar' && <BarChartPreview />}
      {chartType === 'rangeBar' && <RangeBarChartPreview />}
      {chartType === 'line' && <LineChartPreview />}
      {chartType === 'area' && <AreaChartPreview />}
      {chartType === 'scatter' && <ScatterChartPreview />}
      {chartType === 'candlestick' && <CandlestickChartPreview />}
    </Stack>
  );
}

function LineChartPreview() {
  return (
    <React.Fragment>
      <Typography variant="h6" sx={{ alignSelf: 'center' }}>
        Unemployment Rate in United States (1948-2025)
      </Typography>
      <LineChartPro
        {...commonProps}
        {...lineSettings}
        xAxis={[{ ...lineXAxis, ...commonXAxisProps }]}
      />
      <Typography variant="caption">
        Source: Federal Reserve Bank of St. Louis. Updated: Jun 6, 2025 7:46 AM CDT.
      </Typography>
    </React.Fragment>
  );
}

function AreaChartPreview() {
  return (
    <React.Fragment>
      <Typography variant="h6" sx={{ alignSelf: 'center' }}>
        Population by Age Group in 2050 (Projected)
      </Typography>
      <LineChartPro
        {...commonProps}
        {...areaSettings}
        xAxis={[{ ...areaXAxis, ...commonXAxisProps }]}
      />
      <Typography variant="caption">
        Source: World Population Prospects: The 2024 Revision, United Nations.
      </Typography>
    </React.Fragment>
  );
}

function BarChartPreview() {
  return (
    <React.Fragment>
      <Typography variant="h6" sx={{ alignSelf: 'center' }}>
        Share of Primary Energy Consumption from Renewables (2023)
      </Typography>
      <BarChartPro
        {...commonProps}
        {...barSettings}
        xAxis={[{ ...barXAxis, ...commonXAxisProps }]}
      />
      <Typography variant="caption">
        Source: Our World in Data. Updated: 2023.
      </Typography>
    </React.Fragment>
  );
}

function RangeBarChartPreview() {
  return (
    <React.Fragment>
      <Typography variant="h6" sx={{ alignSelf: 'center' }}>
        Average monthly temperature ranges in °C for Porto and Berlin in 1991-2020
      </Typography>
      <BarChartPremium
        {...commonProps}
        {...rangeBarSettings}
        xAxis={[{ ...rangeBarXAxis, ...commonXAxisProps }]}
      />
      <Typography variant="caption">
        Source: IPMA (Porto), climate-data.org (Berlin)
      </Typography>
    </React.Fragment>
  );
}

function ScatterChartPreview() {
  return (
    <React.Fragment>
      <Typography variant="h6" sx={{ alignSelf: 'center' }}>
        Births per woman vs GDP per capita (USD, 2023)
      </Typography>
      <ScatterChartPro
        {...commonProps}
        {...scatterSettings}
        xAxis={[{ ...scatterXAxis, ...commonXAxisProps }]}
      />
      <Typography variant="caption">
        GDP per capita is expressed in international dollars at 2021 prices. <br />
        Source: Our World in Data. Updated: 2023.
      </Typography>
    </React.Fragment>
  );
}

function CandlestickChartPreview() {
  return (
    <React.Fragment>
      <Typography variant="h6" sx={{ alignSelf: 'center' }}>
        S&P 500 Intraday Price
      </Typography>
      <CandlestickChart
        series={[{ data: candlestickData }]}
        xAxis={[
          {
            data: candlestickXData,
            valueFormatter: (v) =>
              v === null ? '' : dayFormatter.format(new Date(v)),
            zoom: {
              minSpan: 1,
              filterMode: 'discard',
              slider: { enabled: true, preview: true },
            },
          },
        ]}
        height={400}
      />
      <Typography variant="caption">Source: Yahoo Finance</Typography>
    </React.Fragment>
  );
}

